@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#131615;--panel:#1b201e;--panel-hi:#212725;--line:#343c38;--muted:#8a938d;--paper:#e9e9de;--acid:#d8f36a;--orange:#f2a471;--mono:'DM Mono',monospace;--sans:'Manrope',sans-serif}*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:var(--ink);color:var(--paper);font:13px var(--sans);overflow:hidden}.app-shell{height:100vh;min-height:650px;display:grid;grid-template-rows:58px 1fr 36px;background:radial-gradient(ellipse at 52% 43%,#252b28 0,#171b19 45%,#111413 100%)}.topbar{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 30px;border-bottom:1px solid #303633;background:#141816;position:relative;z-index:2}.brand{display:flex;gap:10px;align-items:center;color:var(--paper);text-decoration:none;font-size:13px;font-weight:800;letter-spacing:.13em}.brand-mark{width:24px;height:24px;background:var(--acid);color:#182018;display:grid;place-items:center;font-size:15px;clip-path:polygon(0 0,100% 0,100% 72%,72% 100%,0 100%)}.brand-slash{color:var(--acid)}.top-center,.sound-toggle,.eyebrow,.preview-caption,.scene-label,.step-summary,.component-count,.subtotal span,.statusbar,.option-meta,.option-price,.crystal-readout small,.price-readout small,.sale-total span,.sale-total small,.sale-breakdown{font-family:var(--mono);letter-spacing:.07em}.top-center{font-size:9px;color:#8f9992;letter-spacing:.12em;position:absolute;left:50%;transform:translateX(-50%)}.live-dot,.status-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:var(--acid);box-shadow:0 0 9px #d8f36a88;margin-right:8px;vertical-align:1px}.top-divider{color:#535c56;margin:0 8px}.sound-toggle{background:none;border:0;color:#a6afa8;font-size:9px;display:flex;align-items:center;gap:9px;cursor:pointer}.sound-toggle b{font-weight:400;color:#69736c}.sound-toggle.enabled b{color:var(--acid)}.sound-icon{font:18px var(--sans);color:var(--acid)}.workspace{display:grid;grid-template-columns:minmax(230px,270px) minmax(400px,1fr) minmax(285px,335px);gap:0;min-height:0;padding:16px 20px 14px}.left-rail{padding:10px 24px 0 10px;display:flex;flex-direction:column;min-width:0}.rail-heading{display:flex;justify-content:space-between;align-items:flex-end}.eyebrow{display:block;color:#9da79f;font-size:8px;letter-spacing:.14em}.rail-heading h1{font-size:33px;line-height:1.04;letter-spacing:-.065em;margin:12px 0 0;font-weight:600}.rail-heading h1 em,.sale-card h2 em{font-family:Georgia,serif;font-weight:400;color:var(--acid)}.build-number{font:10px var(--mono);text-align:right;color:var(--paper);line-height:1.55;padding-bottom:4px}.build-number span{color:#69736d}.intro-copy{font-size:11px;line-height:1.8;color:#9aa39c;max-width:215px;margin:17px 0 22px}.progress-track{height:2px;background:#333b36;width:100%;margin-bottom:20px}.progress-fill{height:100%;width:20%;background:var(--acid);transition:width .35s}.step-list{display:flex;flex-direction:column;gap:5px}.step-item{border:1px solid transparent;background:transparent;color:#929b94;display:flex;align-items:center;gap:12px;padding:11px 9px;text-align:left;cursor:pointer;transition:.2s;font-family:var(--sans)}.step-item:hover{background:#1b211e}.step-item.active{border-color:#3a443b;background:#202722;color:var(--paper)}.step-item.done .step-index{color:var(--acid);border-color:#637148}.step-index{width:24px;height:24px;border:1px solid #414a44;display:grid;place-items:center;font:9px var(--mono);color:#7b847e;flex:none}.step-copy{display:flex;flex-direction:column;gap:4px}.step-copy strong{font-size:11px;font-weight:600}.step-copy small{font:8px var(--mono);color:#78817a;letter-spacing:.06em}.step-state{margin-left:auto;font-size:11px;color:var(--acid)}.rail-bottom{margin-top:auto;color:#66716a;font:8px var(--mono);letter-spacing:.09em;padding:12px 0 10px;display:flex;align-items:center;gap:8px}.tiny-orbit{font-size:16px;color:var(--acid)}
.preview-panel{border:1px solid #39413c;background:linear-gradient(150deg,#222825,#191e1c 78%);position:relative;display:grid;grid-template-rows:48px minmax(0,1fr) 68px 54px;min-width:0;overflow:hidden}.preview-top{position:absolute;z-index:1;top:15px;left:18px;right:18px;display:flex;justify-content:space-between;align-items:center}.preview-top>div{display:flex;align-items:center;gap:13px}.preview-caption{font-size:8px;color:#849087}.preview-caption span{color:var(--acid);font-size:12px}.icon-button{width:29px;height:29px;border:1px solid #48514b;color:#b5beb6;background:#1a201d;font-size:18px;cursor:pointer;transition:.2s}.icon-button:hover{color:var(--acid);border-color:var(--acid)}.scene-wrap{position:relative;min-height:300px;overflow:hidden;background:radial-gradient(ellipse at 51% 47%,#39443d 0,#242b27 32%,#1d2320 67%,#1a1f1d 100%)}.scene-wrap:before{content:"";position:absolute;inset:0;background-image:linear-gradient(#cbd7c008 1px,transparent 1px),linear-gradient(90deg,#cbd7c008 1px,transparent 1px);background-size:50px 50px;transform:perspective(360px) rotateX(60deg) scale(1.7);transform-origin:50% 80%;opacity:.55;mask-image:linear-gradient(to bottom,transparent 12%,#000 85%)}.scene-wrap canvas{position:absolute;inset:0;width:100%;height:100%;z-index:1;cursor:grab}.scene-wrap canvas:active{cursor:grabbing}.scene-vignette{position:absolute;inset:0;z-index:2;pointer-events:none;background:radial-gradient(ellipse at center,transparent 40%,#14181666 100%)}.scene-loading{position:absolute;z-index:4;inset:0;display:grid;place-content:center;justify-items:center;gap:12px;background:#1c221f;color:#a6b0a7;font:9px var(--mono);letter-spacing:.12em;transition:opacity .5s}.scene-loading span{width:24px;height:24px;border:1px solid #657155;border-top-color:var(--acid);border-radius:50%;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.scene-label{position:absolute;left:17px;bottom:15px;z-index:3;font-size:8px;color:#a6b0a7}.scene-label-right{position:absolute;left:calc(100% - 135px);white-space:nowrap;color:#727d75}.preview-bottom{position:relative;display:flex;align-items:center;justify-content:space-between;padding:0 19px;border-top:1px solid #343c37;border-bottom:1px solid #343c37;background:#1b201e}.preview-bottom>div{display:flex;flex-direction:column;gap:6px}.preview-bottom .eyebrow{font-size:7px}.preview-bottom strong{font-weight:600;font-size:12px}.crystal-readout{flex-direction:row!important;align-items:center;gap:9px!important}.crystal-dot{width:9px;height:9px;border-radius:50%;background:#79aaff;box-shadow:0 0 11px currentColor}.crystal-readout span:last-child{display:flex;flex-direction:column;gap:5px}.crystal-readout small,.price-readout small{font-size:7px;color:#859087}.crystal-readout b{font:9px var(--mono);font-weight:400}.price-readout{text-align:right}.price-readout strong{font:12px var(--mono);color:var(--acid)}.step-controls{display:flex;align-items:center;justify-content:space-between;padding:0 17px}.text-button{background:none;border:0;color:#9ea79f;font:9px var(--mono);letter-spacing:.06em;cursor:pointer}.text-button:disabled{opacity:.3;cursor:default}.step-summary{font-size:8px;color:#768079}.primary-button{background:var(--acid);color:#192019;border:0;padding:12px 16px;font:10px var(--mono);font-weight:500;letter-spacing:.06em;cursor:pointer;transition:transform .18s,background .18s;white-space:nowrap}.primary-button span{font-size:14px;margin-left:12px}.primary-button:hover{background:#e5ff83;transform:translateY(-1px)}.primary-button:active{transform:translateY(0)}
.choice-panel{border:1px solid #343c37;border-left:0;background:#1b201e;padding:22px 19px 0;display:flex;flex-direction:column;min-width:0}.choice-header{display:flex;justify-content:space-between;align-items:flex-end}.choice-header h2{font-size:19px;letter-spacing:-.04em;margin:8px 0 0;font-weight:600}.component-count{font-size:12px;color:var(--paper);padding-bottom:2px}.component-count i{font-style:normal;color:#758078;font-size:9px}.choice-description{font-size:10px;line-height:1.7;color:#909a92;margin:11px 0 19px;max-width:260px;min-height:34px}.option-list{display:flex;flex-direction:column;gap:8px}.option-card{position:relative;border:1px solid #373f3a;background:#202623;padding:11px 10px;cursor:pointer;transition:border-color .2s,background .2s;display:grid;grid-template-columns:37px 1fr auto;align-items:center;gap:10px;text-align:left;color:var(--paper);font-family:var(--sans);min-height:66px}.option-card:hover{border-color:#727d6d;background:#252d28}.option-card.selected{border-color:var(--acid);background:#262e27}.option-card.selected:after{content:"✓";position:absolute;right:8px;top:5px;color:var(--acid);font-size:9px}.option-swatch{height:39px;width:37px;background:linear-gradient(140deg,#818780,#303633 50%,#757c73);position:relative;overflow:hidden}.option-swatch:before{content:"";position:absolute;inset:6px 12px;border-left:2px solid #d5dad1;border-right:2px solid #7a8279;opacity:.65}.option-swatch:after{content:"";position:absolute;left:0;right:0;top:50%;height:2px;background:#171c19;box-shadow:0 4px #aab0a6}.option-swatch.copper{background:linear-gradient(140deg,#d9a77e,#514034 50%,#ac7550)}.option-swatch.onyx{background:linear-gradient(140deg,#747b78,#1a201e 50%,#434b46)}.option-swatch.ivory{background:linear-gradient(140deg,#e1dcc6,#666252 55%,#c2baa4)}.option-swatch.ridged:after{top:23%;height:2px;box-shadow:0 5px #171c19,0 10px #aab0a6,0 15px #171c19}.option-swatch.crystal{background:radial-gradient(circle,#6070ff 0,#384a5c 32%,#202623 72%)}.option-swatch.crystal:before{inset:7px 12px;background:#81aaff;clip-path:polygon(50% 0,100% 30%,82% 100%,18% 100%,0 30%);box-shadow:0 0 10px #82aaff}.option-swatch.crystal:after{display:none}.option-copy{display:flex;flex-direction:column;gap:4px;padding-right:3px}.option-copy strong{font-size:10px;font-weight:600}.option-copy small{font:8px var(--mono);color:#818b83;letter-spacing:.04em}.option-price{font-size:9px;color:#d4dacf;align-self:start;padding-top:3px}.option-card.selected .option-price{color:var(--acid)}.selection-note{margin-top:14px;padding:10px 9px;display:flex;align-items:flex-start;gap:9px;background:#232925;color:#99a39b;font-size:9px;line-height:1.6}.note-icon{color:var(--acid);font-size:13px;line-height:1}.choice-footer{margin-top:auto;border-top:1px solid #373f3a;padding:14px 0 15px;display:flex;align-items:center;justify-content:space-between;gap:8px}.subtotal{display:flex;flex-direction:column;gap:5px}.subtotal span{font-size:7px;color:#808a82}.subtotal strong{font:12px var(--mono);color:var(--acid)}.primary-button.wide{font-size:9px;padding:13px 10px;flex:1}.primary-button.wide span{margin-left:7px}
.statusbar{display:flex;align-items:center;justify-content:space-between;padding:0 30px;border-top:1px solid #303633;background:#141816;color:#78817a;font-size:7px;letter-spacing:.09em}.statusbar>span:first-child{color:#98a299}.status-center{position:absolute;left:50%;transform:translateX(-50%)}.statusbar b{font-size:12px;color:var(--acid);vertical-align:-1px;margin-left:6px}.status-dot{width:5px;height:5px;margin-right:7px}.sale-overlay{position:fixed;inset:0;z-index:10;background:#080b09d9;display:grid;place-items:center;padding:20px;opacity:0;visibility:hidden;transition:opacity .3s,visibility .3s;backdrop-filter:blur(7px)}.sale-overlay.open{opacity:1;visibility:visible}.sale-card{position:relative;width:min(430px,100%);background:#1d2420;border:1px solid #58634f;padding:38px 42px;text-align:center;box-shadow:0 25px 100px #0009}.sale-close{position:absolute;top:12px;right:14px;background:none;border:0;color:#98a198;font-size:24px;cursor:pointer}.sale-spark{font-size:35px;color:var(--acid);margin-bottom:11px;text-shadow:0 0 20px #d8f36a88}.sale-card h2{font-size:29px;letter-spacing:-.06em;line-height:1.12;margin:13px 0}.sale-card p{color:#9ba59d;font-size:11px;line-height:1.8;margin:13px auto 23px;max-width:290px}.sale-total{padding:19px 0 17px;border-top:1px solid #39423b;border-bottom:1px solid #39423b;display:flex;flex-direction:column;gap:8px}.sale-total span,.sale-total small{font-size:8px;color:#9ba59d}.sale-total strong{font:34px var(--mono);color:var(--acid);letter-spacing:-.06em}.sale-total small{font-size:7px;letter-spacing:.15em}.sale-breakdown{display:grid;grid-template-columns:1fr 1fr;gap:10px;text-align:left;margin:16px 0 19px;font-size:8px;color:#9ba59d}.sale-breakdown div{display:flex;justify-content:space-between;border-bottom:1px solid #313a34;padding-bottom:7px;gap:8px}.sale-breakdown b{color:var(--paper);font-weight:400}.toast{position:fixed;z-index:12;left:50%;bottom:54px;transform:translate(-50%,10px);padding:10px 16px;background:#d8f36a;color:#182018;font:9px var(--mono);opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:1050px){.workspace{grid-template-columns:215px minmax(340px,1fr) 290px;padding:12px}.left-rail{padding-right:14px}.choice-panel{padding-left:14px;padding-right:14px}.rail-heading h1{font-size:29px}.option-card{gap:7px;grid-template-columns:32px 1fr auto;padding:9px}.option-swatch{width:32px;height:36px}}@media(max-width:820px){body{overflow:auto}.app-shell{height:auto;min-height:100vh;grid-template-rows:52px auto 34px}.topbar{height:52px;padding:0 14px}.top-center{display:none}.workspace{grid-template-columns:1fr;gap:10px;padding:10px}.left-rail{padding:9px 5px}.rail-heading h1{font-size:25px;margin-top:7px}.intro-copy{margin:8px 0 12px;max-width:450px}.progress-track{margin-bottom:8px}.step-list{display:grid;grid-template-columns:repeat(5,1fr);gap:3px}.step-item{padding:7px 5px;flex-direction:column;align-items:flex-start;gap:4px}.step-index{width:19px;height:19px;font-size:8px}.step-copy{gap:1px}.step-copy strong{font-size:8px}.step-copy small{display:none}.step-state{display:none}.rail-bottom{display:none}.preview-panel{height:min(64vh,560px);min-height:390px;grid-template-rows:1fr 64px 50px}.scene-wrap{grid-row:1}.preview-top{top:12px}.choice-panel{border-left:1px solid #343c37;padding:17px 14px 0}.choice-description{max-width:500px;min-height:0;margin:8px 0 13px}.option-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.option-card{min-height:62px}.selection-note{margin-top:9px}.choice-footer{margin-top:12px}.statusbar{padding:0 12px;font-size:6px}.status-center{display:none}}@media(max-width:460px){.workspace{padding:8px;gap:8px}.preview-panel{height:56vh;min-height:365px}.preview-bottom{padding:0 11px}.preview-bottom strong{font-size:10px}.crystal-readout b{font-size:7px}.price-readout strong{font-size:10px}.choice-header h2{font-size:17px}.option-list{grid-template-columns:1fr}.option-card{min-height:59px}.selection-note{margin-top:8px}.choice-footer{padding:11px 0}.sale-card{padding:35px 24px}.sale-card h2{font-size:25px}}

import * as THREE from 'three';

const steps = [
  { id: 'hilt', title: 'Hilt', kicker: 'THE FOUNDATION', eyebrow: 'STEP 01 · FOUNDATION', heading: 'Choose your hilt', description: 'The heart of your build. A good hilt feels like it was always meant to be yours.', note: 'A balanced classic, made for a steady hand.' },
  { id: 'emitter', title: 'Emitter', kicker: 'THE SIGNATURE', eyebrow: 'STEP 02 · THE SIGNATURE', heading: 'Shape the emitter', description: 'The saber’s silhouette starts here. Pick a profile that makes an entrance.', note: 'The emitter shapes the first impression.' },
  { id: 'grip', title: 'Grip', kicker: 'IN YOUR HAND', eyebrow: 'STEP 03 · IN YOUR HAND', heading: 'Find your grip', description: 'Comfort meets control. Choose the texture that will feel right in every duel.', note: 'A sure grip makes a steady blade.' },
  { id: 'pommel', title: 'Pommel', kicker: 'THE FINISHING TOUCH', eyebrow: 'STEP 04 · FINISHING TOUCH', heading: 'Cap it with character', description: 'A final detail with a little personality. Balance the build from end to end.', note: 'The smallest details stay with you.' },
  { id: 'crystal', title: 'Kyber crystal', kicker: 'FIND YOUR COLOR', eyebrow: 'STEP 05 · THE HEART', heading: 'Choose your crystal', description: 'A crystal is more than a color. It’s the voice of your saber.', note: 'Let the crystal choose you.' },
];
const options = {
  hilt: [
    { name: 'Wayfinder', detail: 'Classic · balanced', price: 620, finish: 'satin', swatch: '', note: 'A balanced classic, made for a steady hand.' },
    { name: 'Dune Walker', detail: 'Brushed copper · rugged', price: 740, finish: 'copper', swatch: 'copper', note: 'Warm copper, built to weather any journey.' },
    { name: 'Nightfall', detail: 'Obsidian · minimalist', price: 890, finish: 'onyx', swatch: 'onyx', note: 'A shadow-dark profile with a quiet confidence.' },
    { name: 'Aureate', detail: 'Ivory alloy · heirloom', price: 1060, finish: 'ivory', swatch: 'ivory', note: 'An elegant heirloom with a light touch.' },
  ],
  emitter: [
    { name: 'Ascendant', detail: 'Flared · classic', price: 360, style: 'flare', note: 'A sweeping flare that frames the blade.' },
    { name: 'Longshot', detail: 'Extended · precise', price: 480, style: 'long', note: 'A long, precise throat for a focused look.' },
    { name: 'Crownpoint', detail: 'Crowned · ornate', price: 610, style: 'crown', note: 'Crowned edges add a hint of ceremony.' },
    { name: 'Venting No. 7', detail: 'Vented · kinetic', price: 720, style: 'vent', note: 'Vented fins give this build a kinetic edge.' },
  ],
  grip: [
    { name: 'Pilgrim wrap', detail: 'Leather · soft touch', price: 220, style: 'wrap', note: 'A soft wrap for long hours on the trail.' },
    { name: 'Crosshatch', detail: 'Knurled · all-weather', price: 310, style: 'knurl', note: 'A tactile crosshatch holds firm in any weather.' },
    { name: 'Field ribs', detail: 'Ridged · secure', price: 380, style: 'ribs', note: 'Close-set ribs add control and a little drama.' },
    { name: 'Core weave', detail: 'Carbon · lightweight', price: 470, style: 'carbon', note: 'Lightweight weave, engineered for speed.' },
  ],
  pommel: [
    { name: 'Dissipator', detail: 'Vented · balanced', price: 180, style: 'vented', note: 'Clean venting keeps the hilt nicely balanced.' },
    { name: 'Anchor cap', detail: 'Weighted · steady', price: 260, style: 'weight', note: 'A weighted cap lends a reassuring counterbalance.' },
    { name: 'Starfang', detail: 'Pronged · striking', price: 350, style: 'fang', note: 'Three sculpted prongs leave a memorable finish.' },
    { name: 'Whisper', detail: 'Low profile · refined', price: 430, style: 'smooth', note: 'A smooth, low-profile ending for a refined build.' },
  ],
  crystal: [
    { name: 'Azure', detail: 'KYBER · steadfast', price: 760, color: '#65aaff', hex: 0x65aaff, note: 'Steadfast and clear. The color of a path well chosen.' },
    { name: 'Verdant', detail: 'KYBER · attuned', price: 920, color: '#8de58c', hex: 0x8de58c, note: 'Attuned to the living Force, bright as new growth.' },
    { name: 'Solaris', detail: 'KYBER · resolute', price: 1080, color: '#ffbf63', hex: 0xffbf63, note: 'A rare golden glow for a resolute spirit.' },
    { name: 'Vesper', detail: 'KYBER · intuitive', price: 1320, color: '#c995ff', hex: 0xc995ff, note: 'Intuitive and uncommon, with a violet heart.' },
    { name: 'Ember', detail: 'KYBER · unbound', price: 1540, color: '#ff6f67', hex: 0xff6f67, note: 'An unbound fire, for those who choose their own way.' },
  ],
};
const selected = { hilt: 0, emitter: 0, grip: 0, pommel: 0, crystal: 0 };
let activeStep = 0;
const $ = (id) => document.getElementById(id);
const money = (amount) => `¤ ${Math.round(amount).toLocaleString('en-US')}`;

function selectedOption(id) { return options[id][selected[id]]; }
function totalValue() {
  const sum = Object.keys(options).reduce((total, key) => total + selectedOption(key).price, 0);
  const choices = Object.values(selected);
  const rarity = new Set(choices).size === 5 ? 280 : 0;
  const material = selected.hilt === 3 && selected.pommel === 3 ? 140 : 0;
  const harmony = selected.emitter === selected.crystal % 4 ? 160 : 0;
  return sum + rarity + material + harmony;
}
function buildName() {
  const hilt = selectedOption('hilt').name;
  const crystal = selectedOption('crystal').name;
  return `${crystal} ${hilt}`;
}
function renderSteps() {
  $('stepList').innerHTML = steps.map((step, index) => `<button class="step-item ${index === activeStep ? 'active' : ''} ${index < activeStep ? 'done' : ''}" data-step="${index}" aria-current="${index === activeStep ? 'step' : 'false'}"><span class="step-index">${index < activeStep ? '✓' : `0${index + 1}`}</span><span class="step-copy"><strong>${step.title}</strong><small>${step.kicker}</small></span>${index === activeStep ? '<span class="step-state">↗</span>' : ''}</button>`).join('');
  document.querySelectorAll('.step-item').forEach(button => button.addEventListener('click', () => setStep(Number(button.dataset.step))));
  $('progressFill').style.width = `${((activeStep + 1) / steps.length) * 100}%`;
  document.querySelector('.build-number').innerHTML = `0${activeStep + 1}<br><span>/ 05</span>`;
  $('stepSummary').innerHTML = `0${activeStep + 1} / 05 &nbsp; ${steps[activeStep].title.toUpperCase()}`;
  $('scene-label-right').textContent = `0${activeStep + 1} — 05`;
  $('prevStep').disabled = activeStep === 0;
  const isLast = activeStep === steps.length - 1;
  $('nextStep').innerHTML = isLast ? 'SELL SABER <span>↗</span>' : 'NEXT PART <span>→</span>';
  $('finishButton').innerHTML = isLast ? 'FINISH & SELL <span>↗</span>' : 'NEXT PART <span>→</span>';
}
function renderOptions() {
  const step = steps[activeStep];
  const list = options[step.id];
  $('categoryEyebrow').textContent = step.eyebrow;
  $('categoryTitle').textContent = step.heading;
  $('categoryDescription').textContent = step.description;
  $('componentCount').innerHTML = `0${selected[step.id] + 1} <i>/ 0${list.length}</i>`;
  $('optionList').innerHTML = list.map((option, index) => {
    const swatch = option.swatch === undefined ? (step.id === 'crystal' ? 'crystal' : option.style === 'ribs' || option.style === 'crown' ? 'ridged' : '') : option.swatch;
    const swatchStyle = step.id === 'crystal' ? ` style="--crystal:${option.color};background:radial-gradient(circle,${option.color} 0,#384a5c 32%,#202623 72%)"` : '';
    const title = step.id === 'crystal' ? `Kyber · ${option.name}` : option.name;
    return `<button class="option-card ${selected[step.id] === index ? 'selected' : ''}" data-option="${index}" aria-pressed="${selected[step.id] === index}"><span class="option-swatch ${swatch}"${swatchStyle}></span><span class="option-copy"><strong>${title}</strong><small>${option.detail}</small></span><span class="option-price">${money(option.price)}</span></button>`;
  }).join('');
  document.querySelectorAll('.option-card').forEach(button => button.addEventListener('click', () => {
    selected[step.id] = Number(button.dataset.option);
    renderOptions(); updateUI(); rebuildSaber(); playTone(480 + activeStep * 70, .07);
  }));
  $('selectionNote').textContent = selectedOption(step.id).note;
  $('partValue').textContent = money(selectedOption(step.id).price);
}
function setStep(index) {
  activeStep = Math.max(0, Math.min(steps.length - 1, index));
